INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-1200-2', '2025-07', 'S3_3_3', 'Vereinfachtes Validierungsmonitoring — Beurteilung der 16 gepaarten Proben je Wassergüteklasse (§3.3.3)', '§3.3.3', NULL, ARRAY['klasse']::text[], '[{"name":"n_total","type":"number"},{"name":"n_pass_min","type":"number"},{"name":"max_shortfall_log10","type":"number","unit":"log10"},{"name":"nachweisgrenze_regel","type":"string"}]'::jsonb, 'locked', 'Beim vereinfachten Validierungsmonitoring werden die zu validierenden $\log _{10}$-Reduktionen für den gesamten Aufbereitungszug auf Basis eines paarweisen Vergleichs von Zu- und Ablaufproben (sogenannter Binomialansatz) nachgewiesen. Dabei werden $\log _{10}$-Reduktionen jeweils paarweise aus korrespondierenden Zu- und Ablaufproben berechnet. Abweichend von der Mindestanzahl gemäß EU-WasserWVVO (mindestens drei Proben pro Stichprobenpunkt) und in Anlehnung an die EU-Badegewässerrichtlinie 2006/7/EG sind je 16 korrespondierende Proben im Zulauf und Ablauf zu nehmen. Die Beurteilung erfolgt wie folgt: — I Wassergüte-Klasse A: In mindestens 15 der 16 Proben muss das Leistungsziel für den jeweiligen Indikatororganismus erreicht oder überschritten werden. Falls das Leistungsziel einmal nicht erreicht wird, darf dieses um nicht mehr als $1,0 \log _{10}$-Stufen unterschritten werden. Das Leistungsziel gilt hierbei ebenfalls als erreicht, wenn der Indikatororganismus in der Ablaufprobe mit < 1 KBE bzw. PFU je 100 ml Probenvolumen vorliegt.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
