SELECT id, 'uv', '{"stufe":"uv"}'::jsonb, NULL, 'UV-Desinfektion', 2, '{"bezeichnung":"UV-Desinfektion","mechanismen":"Inaktivierung der DNA-Replikationsfähigkeit von Mikroorganismen durch UV-Bestrahlung","einflussfaktoren":"Durchflussrate, Bestrahlungsdosis, UV-Transmission des Wassers","methodik":"Prävalidierung: Erfolgt in der Regel durch den Hersteller gemäß DVGW W 294 (nicht für Viren) bzw. der EPAGuideline. Nachweis einer Referenzdosis $\\geqslant 40 \\mathrm{~mJ} / \\mathrm{cm}^{2}$, Definition der erforderlichen Betriebsparameter, Zuordnung von $\\log _{10}$-Reduktionen in Abhängigkeit von der UV-Transmission. Der Nachweis nach EPA-Guideline erfolgt produktspezifisch anhand eines der folgenden Ansätze:\n1. UV-Intensitäts-Setpoint-Ansatz\n2. Ansatz der berechneten RED lengl. „Reduction Equivalent Dose“, empfohlene Challenge-Mikroorganismen: MS2- und T1UV-Phagen) mit RED = f (Durchfluss, UV Transmissivität des Wassers, UVLampenleistung, UV-Intensität am Sensor gemessen, Validierungsfaktor). Diese berechnete Dosis wird mit den tabellierten UVDosen zur Inaktivierung für Giardia, Cryptosporidium und Viren verglichen).\nBetriebliche Überwachung: Überwachung der relevanten Parameter (Durchfluss, Lampenstatus, UVIntensität, Licht-Transmission, Trübung).","referenz":"WaterSecure (2017c), Hoyer (1998), DVGW W 294-1 (A): (2023), US EPA:2006, US EPA:2017"}'::jsonb, '\hline UV-Desinfektion & Inaktivierung der DNA-Replikationsfähigkeit von Mikroorganismen durch UV-Bestrahlung & Durchflussrate, Bestrahlungsdosis, UV-Transmission des Wassers & \begin{tabular}{l}
Prävalidierung: Erfolgt in der Regel durch den Hersteller gemäß DVGW W 294 (nicht für Viren) bzw. der EPAGuideline. Nachweis einer Referenzdosis $\geqslant 40 \mathrm{~mJ} / \mathrm{cm}^{2}$, Definition der erforderlichen Betriebsparameter, Zuordnung von $\log _{10}$-Reduktionen in Abhängigkeit von der UV-Transmission. Der Nachweis nach EPA-Guideline erfolgt produktspezifisch anhand eines der folgenden Ansätze: \\
1. UV-Intensitäts-Setpoint-Ansatz \\
2. Ansatz der berechneten RED lengl. „Reduction Equivalent Dose“, empfohlene Challenge-Mikroorganismen: MS2- und T1UV-Phagen) mit RED = f (Durchfluss, UV Transmissivität des Wassers, UVLampenleistung, UV-Intensität am Sensor gemessen, Validierungsfaktor). Diese berechnete Dosis wird mit den tabellierten UVDosen zur Inaktivierung für Giardia, Cryptosporidium und Viren verglichen). \\
Betriebliche Überwachung: Überwachung der relevanten Parameter (Durchfluss, Lampenstatus, UVIntensität, Licht-Transmission, Trübung).
\end{tabular} & WaterSecure (2017c), Hoyer (1998), DVGW W 294-1 (A): (2023), US EPA:2006, US EPA:2017 \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TAB4'
