SELECT id, 'chlor', '{"stufe":"chlor"}'::jsonb, NULL, 'Chlorbasierte Desinfektion lanalog auch andere chemische Desinfektion)', 3, '{"bezeichnung":"Chlorbasierte Desinfektion lanalog auch andere chemische Desinfektion)","mechanismen":"Inaktivierung durch Oxidationsreaktionen mit z. B. Zellwänden oder genetischem Material Restchlorgehalte ermöglichen De-pot-Wirkung","einflussfaktoren":"Durchflussrate, Applizierte ChlorDosis (Ct-Wert = Konzentration • Kontaktzeit), pHWert (bestimmt Speziierung der ChlorKomponenten), Temperatur, Trübung, Zehrstoffe, residuale Chlor-Konzentration","methodik":"Nachweis des Ct-Werts in der großtechnischen Anlage: hydraulische Charakterisierung (Verweilzeitverteilung) des Desinfektionsreaktors, ggf. durch Strömungssimulation und/oder Tracer-Versuch.\nAlternative: Challenge-Test mit Zielorganismen für Validierung.\nBetriebliches Monitoring muss relevante Parameter möglichst kontinuierlich überwachen, um Einhaltung des Ct-Werts zu überprüfen.","referenz":"WaterSecure (2017d), US EPA:1999"}'::jsonb, '\hline Chlorbasierte Desinfektion lanalog auch andere chemische Desinfektion) & Inaktivierung durch Oxidationsreaktionen mit z. B. Zellwänden oder genetischem Material Restchlorgehalte ermöglichen De-pot-Wirkung & Durchflussrate, Applizierte ChlorDosis (Ct-Wert = Konzentration • Kontaktzeit), pHWert (bestimmt Speziierung der ChlorKomponenten), Temperatur, Trübung, Zehrstoffe, residuale Chlor-Konzentration & \begin{tabular}{l}
Nachweis des Ct-Werts in der großtechnischen Anlage: hydraulische Charakterisierung (Verweilzeitverteilung) des Desinfektionsreaktors, ggf. durch Strömungssimulation und/oder Tracer-Versuch. \\
Alternative: Challenge-Test mit Zielorganismen für Validierung. \\
Betriebliches Monitoring muss relevante Parameter möglichst kontinuierlich überwachen, um Einhaltung des Ct-Werts zu überprüfen.
\end{tabular} & WaterSecure (2017d), US EPA:1999 \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TAB4'
