SELECT id, 'ozon', '{"stufe":"ozon"}'::jsonb, NULL, 'Ozonbasierte Desinfektion', 4, '{"bezeichnung":"Ozonbasierte Desinfektion","mechanismen":"Inaktivierung durch Oxidationsreaktionen mit z. B. Zellwänden oder genetischem Material, präferentielle Reaktionen mit elektronenreichen Molekülbereichen (z. B. Koh-lenstoff-Stick-stoff-Bindungen)","einflussfaktoren":"Ozon-Konzentration, applizierte Ozon-Dosis lggf. bezogen auf DOC), Temperatur, pHWert, Trübung, DOC, Ozon-zehrende Verbindungen, hydraulische Charakteristik","methodik":"Nachweis der Desinfektionsleistung in Abhängigkeit von der spezifischen Ozondosis (g $\\mathrm{O}_{3} / \\mathrm{g}$ DOC) und sekundär weitere Einflussfaktoren wie Trübung, Ozon-zehrende Verbindungen (Ammonium, Nitrit) und pH. Der Reaktor muss hydraulisch charakterisiert sein durch Strömungssimulationen und/oder Tracer-Versuche. Die Einflussfaktoren sind im Betrieb auf geeignete Weise zu überwachen. Da in Deutschland in der Regel Ozon so dosiert wird, dass kein Restozongehalt gemessen werden kann, kann der Validierungsansatz auf Basis des Ct-Werts (WaterSecure 2017b) in der Regel nicht angewendet werden.","referenz":"WaterSecure (2017b)"}'::jsonb, '\hline Ozonbasierte Desinfektion & Inaktivierung durch Oxidationsreaktionen mit z. B. Zellwänden oder genetischem Material, präferentielle Reaktionen mit elektronenreichen Molekülbereichen (z. B. Koh-lenstoff-Stick-stoff-Bindungen) & Ozon-Konzentration, applizierte Ozon-Dosis lggf. bezogen auf DOC), Temperatur, pHWert, Trübung, DOC, Ozon-zehrende Verbindungen, hydraulische Charakteristik & Nachweis der Desinfektionsleistung in Abhängigkeit von der spezifischen Ozondosis (g $\mathrm{O}_{3} / \mathrm{g}$ DOC) und sekundär weitere Einflussfaktoren wie Trübung, Ozon-zehrende Verbindungen (Ammonium, Nitrit) und pH. Der Reaktor muss hydraulisch charakterisiert sein durch Strömungssimulationen und/oder Tracer-Versuche. Die Einflussfaktoren sind im Betrieb auf geeignete Weise zu überwachen. Da in Deutschland in der Regel Ozon so dosiert wird, dass kein Restozongehalt gemessen werden kann, kann der Validierungsansatz auf Basis des Ct-Werts (WaterSecure 2017b) in der Regel nicht angewendet werden. & WaterSecure (2017b) \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TAB4'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
