SELECT id, 'mf_uf', '{"stufe":"mf_uf"}'::jsonb, NULL, 'Mikrofiltration und Ultrafiltration', 5, '{"bezeichnung":"Mikrofiltration und Ultrafiltration","mechanismen":"Rückhalt durch dichte trennaktive Schicht der porösen Membranen in Folge von Größenausschluss (Siebeffekt) sowie teilweise Ladungseffekte lelektrostatische Abstoßung) und Adsorption","einflussfaktoren":"Membraneigenschaften (Porendurchmesser, Oberflächenladung, Hydrophobizität), Membranmodul, Betriebsbedingungen (z. B. Permeatfluss, Transmembrandruck, Wasserausbeute, Überströmung), Wasserqualität (pH, Temperatur, lonenstärke, DOC), Membran-integrität, Fouling und Scaling","methodik":"In der Regel sollte eine Vorab-Validierung des Membransystems durch den Anbieter erfolgen. Dabei ist ein ,,Challenge-Test\" z. B. mit MS2Phagen als Indikatoren in einem typischen (konservativen) Betriebsregime durchzuführen. Bei der ..NSF 419\"-Zertifizierung wird die minimale und mittlere $\\log _{10}$-Reduktion für Viren bzw. Cryptosporidium mitsamt des maximal zugelassenen Permeatflusses angegeben. Im Betrieb ist die Integrität fortlaufend oder zumindest regelmäßig zu überwachen. Verschiedene Integritätstests können kontinuierlich (z. B. Trübungsmessung oder Partikelzählung im Permeat) oder diskontinuierlich (z. B. Druckhaltetest, Blasentest oder Spiking-Test) durchgeführt werden.","referenz":"US EPA:1991, US EPA:2001, DVGW W 2135 (A), DVGW W 2136 (A), NSF/ANSI 419"}'::jsonb, '\hline Mikrofiltration und Ultrafiltration & Rückhalt durch dichte trennaktive Schicht der porösen Membranen in Folge von Größenausschluss (Siebeffekt) sowie teilweise Ladungseffekte lelektrostatische Abstoßung) und Adsorption & Membraneigenschaften (Porendurchmesser, Oberflächenladung, Hydrophobizität), Membranmodul, Betriebsbedingungen (z. B. Permeatfluss, Transmembrandruck, Wasserausbeute, Überströmung), Wasserqualität (pH, Temperatur, lonenstärke, DOC), Membran-integrität, Fouling und Scaling & In der Regel sollte eine Vorab-Validierung des Membransystems durch den Anbieter erfolgen. Dabei ist ein ,,Challenge-Test" z. B. mit MS2Phagen als Indikatoren in einem typischen (konservativen) Betriebsregime durchzuführen. Bei der ..NSF 419"-Zertifizierung wird die minimale und mittlere $\log _{10}$-Reduktion für Viren bzw. Cryptosporidium mitsamt des maximal zugelassenen Permeatflusses angegeben. Im Betrieb ist die Integrität fortlaufend oder zumindest regelmäßig zu überwachen. Verschiedene Integritätstests können kontinuierlich (z. B. Trübungsmessung oder Partikelzählung im Permeat) oder diskontinuierlich (z. B. Druckhaltetest, Blasentest oder Spiking-Test) durchgeführt werden. & US EPA:1991, US EPA:2001, DVGW W 2135 (A), DVGW W 2136 (A), NSF/ANSI 419 \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TAB4'
