SELECT id, 'ro_nf', '{"stufe":"ro_nf"}'::jsonb, NULL, 'Umkehrosmose und Nanofiltration', 6, '{"bezeichnung":"Umkehrosmose und Nanofiltration","mechanismen":"Rückhalt durch dichte trennaktive Schicht laus Polyamid) der dichten Membranen in Folge von Größenausschluss (Siebeffekt), Ladungseffekte lelektrostatische Abstoßung), Adsorption","einflussfaktoren":"Membraneigenschaften lengl. .,Molecular Weight Cut-off\", Oberflächenladung, Hydrophobizität), Membranmodul (z. B. Spiralwickelmodul), Betriebsbedingungen (Permeatfluss, Transmembrandruck, Wasserausbeute, Überströmung), Wasserqualität (pH, Temperatur, lonenstärke, DOC), Membranintegrität, Fouling und Scaling","methodik":"In der Regel sollte eine Vorab-Validierung des Membransystems durch den Anbieter erfolgen. Dabei ist ein .,Chal-lenge-Test\" z. B. mit MS2-Phagen als Indikatoren in einem typischen (konservativen) Betriebsregime durchzuführen. Weiterhin ist ein kontinuierlich (online) messbarer Parameter festzulegen, der zur betrieblichen Integritätskontrolle verwendet wird (z. B. Leitfähigkeit oder TOC). Die Integrität muss durch den entsprechenden Parameter fortlaufend im Betrieb überwacht werden. Falls es zu größeren Abweichungen im Betriebsregime kommt oder der OnlineParameter keine aussagekräftigen Informationen liefert, wird ein „Chal-lenge-Test\" in der großtechnischen Anlage empfohlen.","referenz":"WaterSecure (2017e)"}'::jsonb, '\hline Umkehrosmose und Nanofiltration & Rückhalt durch dichte trennaktive Schicht laus Polyamid) der dichten Membranen in Folge von Größenausschluss (Siebeffekt), Ladungseffekte lelektrostatische Abstoßung), Adsorption & Membraneigenschaften lengl. .,Molecular Weight Cut-off", Oberflächenladung, Hydrophobizität), Membranmodul (z. B. Spiralwickelmodul), Betriebsbedingungen (Permeatfluss, Transmembrandruck, Wasserausbeute, Überströmung), Wasserqualität (pH, Temperatur, lonenstärke, DOC), Membranintegrität, Fouling und Scaling & In der Regel sollte eine Vorab-Validierung des Membransystems durch den Anbieter erfolgen. Dabei ist ein .,Chal-lenge-Test" z. B. mit MS2-Phagen als Indikatoren in einem typischen (konservativen) Betriebsregime durchzuführen. Weiterhin ist ein kontinuierlich (online) messbarer Parameter festzulegen, der zur betrieblichen Integritätskontrolle verwendet wird (z. B. Leitfähigkeit oder TOC). Die Integrität muss durch den entsprechenden Parameter fortlaufend im Betrieb überwacht werden. Falls es zu größeren Abweichungen im Betriebsregime kommt oder der OnlineParameter keine aussagekräftigen Informationen liefert, wird ein „Chal-lenge-Test" in der großtechnischen Anlage empfohlen. & WaterSecure (2017e) \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TAB4'
