VALUES ('DWA-M-1200-2', '2025-07', 'TABB2', 'Indikative log10-Reduktionen je Aufbereitungsstufe — erreichbar / erwartbar für Viren, Protozoen, Bakterien (Tab. B.2)', 'Anhang B, Tab. B.2', NULL, ARRAY['stufe']::text[], '[{"name":"bezeichnung","type":"string"},{"name":"viren_erreichbar","type":"number","unit":"log10"},{"name":"protozoen_erreichbar","type":"number","unit":"log10"},{"name":"bakterien_erreichbar","type":"number","unit":"log10"},{"name":"viren_erwartbar_text","type":"string"},{"name":"viren_erwartbar_min","type":"number","unit":"log10"},{"name":"viren_erwartbar_max","type":"number","unit":"log10"},{"name":"protozoen_erwartbar_text","type":"string"},{"name":"protozoen_erwartbar_min","type":"number","unit":"log10"},{"name":"protozoen_erwartbar_max","type":"number","unit":"log10"},{"name":"bakterien_erwartbar_text","type":"string"},{"name":"bakterien_erwartbar_min","type":"number","unit":"log10"},{"name":"bakterien_erwartbar_max","type":"number","unit":"log10"},{"name":"erwartbar_gemeinsam","type":"boolean"},{"name":"anmerkung","type":"string"}]'::jsonb, 'anhaltswert', 'Tabelle B.2: Indikative $\log _{10}$-Reduktionen, denen Aufbereitungsstufen zuzuordnen sind (Australian Guidelines for Water Recycling, Draft of Chapters 1, 2, 3 and 5 and Appendices 2 and 3, 2020), mit Ergänzungen zur Einordnung — können als Alternativvariante $\log _{10}$-Reduktionen und Betriebsdaten aus weiteren Quellen herangezogen werden,', 'md_verified')
