SELECT id, 'biologisch', '{"stufe":"biologisch"}'::jsonb, NULL, 'Biologische Behandlung (secondary treatment)', 1, '{"bezeichnung":"Biologische Behandlung (secondary treatment)","viren_erreichbar":2,"protozoen_erreichbar":2,"bakterien_erreichbar":2,"viren_erwartbar_text":"0,5-1","viren_erwartbar_min":0.5,"viren_erwartbar_max":1,"protozoen_erwartbar_text":"0,5-1","protozoen_erwartbar_min":0.5,"protozoen_erwartbar_max":1,"bakterien_erwartbar_text":"1-2","bakterien_erwartbar_min":1,"bakterien_erwartbar_max":2,"erwartbar_gemeinsam":false,"anmerkung":"Konservative Standardwerte auf der Grundlage der berichteten Ergebnisse ${ }^{11,2,3]}$. Diese können auf der Grundlage von systemspezifischen Tests zur Reduzierung von Pathogenen erhöht werden. In Ermangelung solcher Studien wurden nominale $\\log _{10}$-Reduktionswerte von $0,5 \\mathrm{Log}$ für Protozoen und bis zu 1 Log für Bakterien, Viren und Helminthen angewendet ${ }^{2 \\text { ). }}$"}'::jsonb, '\hline Biologische Behandlung (secondary treatment) & 2 & 2 & 2 & 0,5-1 & 0,5-1 & 1-2 & Konservative Standardwerte auf der Grundlage der berichteten Ergebnisse ${ }^{11,2,3]}$. Diese können auf der Grundlage von systemspezifischen Tests zur Reduzierung von Pathogenen erhöht werden. In Ermangelung solcher Studien wurden nominale $\log _{10}$-Reduktionswerte von $0,5 \mathrm{Log}$ für Protozoen und bis zu 1 Log für Bakterien, Viren und Helminthen angewendet ${ }^{2 \text { ). }}$ \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
