SELECT id, 'ozon', '{"stufe":"ozon"}'::jsonb, NULL, 'Ozon mit oder ohne biologische Nachbehandlung (z. B. biologisch aktivierte Aktivkohlefiltration)', 5, '{"bezeichnung":"Ozon mit oder ohne biologische Nachbehandlung (z. B. biologisch aktivierte Aktivkohlefiltration)","viren_erreichbar":4,"protozoen_erreichbar":3,"bakterien_erreichbar":4,"viren_erwartbar_text":"4","viren_erwartbar_min":4,"viren_erwartbar_max":4,"protozoen_erwartbar_text":"0","protozoen_erwartbar_min":0,"protozoen_erwartbar_max":0,"bakterien_erwartbar_text":"4","bakterien_erwartbar_min":4,"bakterien_erwartbar_max":4,"erwartbar_gemeinsam":false,"anmerkung":"Die $\\log _{10}$-Reduktionen basieren auf dem Erreichen einer (residualen) Ozonkonzentration*Zeit von $1 \\mathrm{mg} \\cdot \\mathrm{min} / \\mathrm{l}$ bei $\\geqslant 10^{\\circ} \\mathrm{C}$. ${ }^{9,111,12]}$ Höhere Konzentrationen können die $\\log _{10}$-Reduktionen erhöhen. ${ }^{\\mathrm{e}}$"}'::jsonb, '\hline Ozon mit oder ohne biologische Nachbehandlung (z. B. biologisch aktivierte Aktivkohlefiltration) & 4 & 3 & 4 & 4 & 0 & 4 & Die $\log _{10}$-Reduktionen basieren auf dem Erreichen einer (residualen) Ozonkonzentration*Zeit von $1 \mathrm{mg} \cdot \mathrm{min} / \mathrm{l}$ bei $\geqslant 10^{\circ} \mathrm{C}$. ${ }^{9,111,12]}$ Höhere Konzentrationen können die $\log _{10}$-Reduktionen erhöhen. ${ }^{\mathrm{e}}$ \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'ro', '{"stufe":"ro"}'::jsonb, NULL, 'Umkehrosmose (RO)', 6, '{"bezeichnung":"Umkehrosmose (RO)","viren_erreichbar":6,"protozoen_erreichbar":6,"bakterien_erreichbar":6,"viren_erwartbar_text":"1,5-4","viren_erwartbar_min":1.5,"viren_erwartbar_max":4,"protozoen_erwartbar_text":"1,5-4","protozoen_erwartbar_min":1.5,"protozoen_erwartbar_max":4,"bakterien_erwartbar_text":"1,5-4","bakterien_erwartbar_min":1.5,"bakterien_erwartbar_max":4,"erwartbar_gemeinsam":true,"anmerkung":"Anlagen zur Umkehrosmose erreichen in der Praxis sehr viel größere $\\log _{10}$ Reduktionswerte als diejenigen, die routinemäßig und ohne Weiteres validiert werden können. Folglich können $\\log _{10}$-Reduktionen in der Größenordnung von $1 \\log _{10}$ bis $2 \\log _{10}$-Stufen routinemäßig validiert werden, wenn die Online-Betriebsüberwachung von Leitfähigkeit oder TOC den kritischen Grenzparameter bildet. $\\log _{1_{0}}$-Reduktionen von 2,5 bis 4 können erreicht werden, wenn die operative Online- oder Offline-Überwachung von Sulfat oder Fluoreszenzfarbstoffen den kritischen Grenzwertparameter darstellt. ${ }^{315,133}$"}'::jsonb, '\hline Umkehrosmose (RO) & 6 & 6 & 6 & \multicolumn{3}{|c|}{1,5-4} & Anlagen zur Umkehrosmose erreichen in der Praxis sehr viel größere $\log _{10}$ Reduktionswerte als diejenigen, die routinemäßig und ohne Weiteres validiert werden können. Folglich können $\log _{10}$-Reduktionen in der Größenordnung von $1 \log _{10}$ bis $2 \log _{10}$-Stufen routinemäßig validiert werden, wenn die Online-Betriebsüberwachung von Leitfähigkeit oder TOC den kritischen Grenzparameter bildet. $\log _{1_{0}}$-Reduktionen von 2,5 bis 4 können erreicht werden, wenn die operative Online- oder Offline-Überwachung von Sulfat oder Fluoreszenzfarbstoffen den kritischen Grenzwertparameter darstellt. ${ }^{315,133}$ \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
