SELECT id, 'uv', '{"stufe":"uv"}'::jsonb, NULL, 'Desinfektion mit ultra-violettem Licht (UV)', 7, '{"bezeichnung":"Desinfektion mit ultra-violettem Licht (UV)","viren_erreichbar":6,"protozoen_erreichbar":6,"bakterien_erreichbar":6,"viren_erwartbar_text":"4","viren_erwartbar_min":4,"viren_erwartbar_max":4,"protozoen_erwartbar_text":"4","protozoen_erwartbar_min":4,"protozoen_erwartbar_max":4,"bakterien_erwartbar_text":"4","bakterien_erwartbar_min":4,"bakterien_erwartbar_max":4,"erwartbar_gemeinsam":true,"anmerkung":"Eine validierte Niederdrucklampen-UV-Dosis von $186 \\mathrm{~mJ} / \\mathrm{cm}^{2}$ kann eine Inaktivierung von $4 \\log _{10}$-Stufen für Viren bewirken. Eine UV-Dosis von $22 \\mathrm{~mJ} / \\mathrm{cm}^{2}$ kann eine Inaktivierung von 4 Log $_{10}$-Stufen für Protozoen und Bakterien bewirken. ${ }^{9,14,15), 161,17)}$"}'::jsonb, '\hline Desinfektion mit ultra-violettem Licht (UV) & 6 & 6 & 6 & \multicolumn{3}{|c|}{4} & Eine validierte Niederdrucklampen-UV-Dosis von $186 \mathrm{~mJ} / \mathrm{cm}^{2}$ kann eine Inaktivierung von $4 \log _{10}$-Stufen für Viren bewirken. Eine UV-Dosis von $22 \mathrm{~mJ} / \mathrm{cm}^{2}$ kann eine Inaktivierung von 4 Log $_{10}$-Stufen für Protozoen und Bakterien bewirken. ${ }^{9,14,15), 161,17)}$ \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
