SELECT id, 'chlor', '{"stufe":"chlor"}'::jsonb, NULL, 'Chlor ( $\mathrm{Cl}_{2}$ )', 9, '{"bezeichnung":"Chlor ( $\\mathrm{Cl}_{2}$ )","viren_erreichbar":6,"protozoen_erreichbar":0,"bakterien_erreichbar":6,"viren_erwartbar_text":"4","viren_erwartbar_min":4,"viren_erwartbar_max":4,"protozoen_erwartbar_text":"0","protozoen_erwartbar_min":0,"protozoen_erwartbar_max":0,"bakterien_erwartbar_text":"4","bakterien_erwartbar_min":4,"bakterien_erwartbar_max":4,"erwartbar_gemeinsam":false,"anmerkung":"Ein Ct-Wert, der mit einer Inaktivierung von $4 \\log _{10}$-Stufen für Viren lund Bakterien) verbunden ist, beträgt $\\geqslant 15 \\mathrm{mg} \\cdot \\mathrm{min} / \\mathrm{l}(\\mathrm{d} . \\mathrm{h} .0,5 \\mathrm{mg} / \\mathrm{l}$ für 30 min$)$ bei einem pH -Wert $\\leqslant 7,5$ und einer Temperatur von $\\geqslant 10^{\\circ} \\mathrm{C}$. ${ }^{9,18], 197}$"}'::jsonb, '\hline Chlor ( $\mathrm{Cl}_{2}$ ) & 6 & 0 & 6 & 4 & 0 & 4 & Ein Ct-Wert, der mit einer Inaktivierung von $4 \log _{10}$-Stufen für Viren lund Bakterien) verbunden ist, beträgt $\geqslant 15 \mathrm{mg} \cdot \mathrm{min} / \mathrm{l}(\mathrm{d} . \mathrm{h} .0,5 \mathrm{mg} / \mathrm{l}$ für 30 min$)$ bei einem pH -Wert $\leqslant 7,5$ und einer Temperatur von $\geqslant 10^{\circ} \mathrm{C}$. ${ }^{9,18], 197}$ \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
