SELECT id, 'boden_aquifer', '{"stufe":"boden_aquifer"}'::jsonb, NULL, 'Boden-Aquifer-Behandlung (Oberflächenausbringung, Sickerwasserreinigung)', 10, '{"bezeichnung":"Boden-Aquifer-Behandlung (Oberflächenausbringung, Sickerwasserreinigung)","viren_erreichbar":6,"protozoen_erreichbar":6,"bakterien_erreichbar":6,"viren_erwartbar_text":"systemspezifisch","viren_erwartbar_min":null,"viren_erwartbar_max":null,"protozoen_erwartbar_text":"systemspezifisch","protozoen_erwartbar_min":null,"protozoen_erwartbar_max":null,"bakterien_erwartbar_text":"systemspezifisch","bakterien_erwartbar_min":null,"bakterien_erwartbar_max":null,"erwartbar_gemeinsam":true,"anmerkung":"Die Log-Reduktionen sind abhängig von der Bodenbeschaffenheit, sowie von den Bedingungen und der Verweilzeit im Grundwasserleiter. ${ }^{4,51,6)}$"}'::jsonb, '\hline Boden-Aquifer-Behandlung (Oberflächenausbringung, Sickerwasserreinigung) & 6 & 6 & 6 & \multicolumn{3}{|c|}{systemspezifisch} & Die Log-Reduktionen sind abhängig von der Bodenbeschaffenheit, sowie von den Bedingungen und der Verweilzeit im Grundwasserleiter. ${ }^{4,51,6)}$ \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
