SELECT id, 'teiche', '{"stufe":"teiche"}'::jsonb, NULL, 'Teiche', 11, '{"bezeichnung":"Teiche","viren_erreichbar":5,"protozoen_erreichbar":5,"bakterien_erreichbar":5,"viren_erwartbar_text":"systemspezifisch","viren_erwartbar_min":null,"viren_erwartbar_max":null,"protozoen_erwartbar_text":"systemspezifisch","protozoen_erwartbar_min":null,"protozoen_erwartbar_max":null,"bakterien_erwartbar_text":"systemspezifisch","bakterien_erwartbar_min":null,"bakterien_erwartbar_max":null,"erwartbar_gemeinsam":true,"anmerkung":"Die $\\log _{10}$-Reduktionen hängen vom Design der Teiche und der Verweilzeit ab. Bei einer minimalen hydraulischen Verweilzeit (lunter Berücksichtigung von Kurzschlüssen) von gesicherten $\\geqslant 25$ Tagen kann eine Reduzierung der Helminthen um $4 \\log _{10}$ angenommen werden. Die $\\log _{10}$-Reduktionen für andere Krankheitserreger sind variabler und können bis auf 1 Log absinken ${ }^{10]}$."}'::jsonb, '\hline Teiche & 5 & 5 & 5 & \multicolumn{3}{|c|}{systemspezifisch} & Die $\log _{10}$-Reduktionen hängen vom Design der Teiche und der Verweilzeit ab. Bei einer minimalen hydraulischen Verweilzeit (lunter Berücksichtigung von Kurzschlüssen) von gesicherten $\geqslant 25$ Tagen kann eine Reduzierung der Helminthen um $4 \log _{10}$ angenommen werden. Die $\log _{10}$-Reduktionen für andere Krankheitserreger sind variabler und können bis auf 1 Log absinken ${ }^{10]}$. \\' FROM regulation_tables WHERE standard_code = 'DWA-M-1200-2' AND edition = '2025-07' AND table_code = 'TABB2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
