INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-1200-2', '2025-07', 'S8_2_KOSTEN', 'Spezifische Kosten je Aufbereitungsstufe in €/m³ Schmutzwasser, Preisstand 2020 (§8.2)', '§8.2', NULL, ARRAY['stufe']::text[], '[{"name":"bezeichnung","type":"string"},{"name":"kosten_min_eur_m3","type":"number","unit":"€/m³ SW"},{"name":"kosten_max_eur_m3","type":"number","unit":"€/m³ SW"},{"name":"zusaetzlich","type":"boolean"},{"name":"bezugsjahr","type":"number"},{"name":"gedruckt","type":"string"}]'::jsonb, 'anhaltswert', 'Für die einzelnen Stufen der Wasseraufbereitung sind nachfolgend spezifische Kosten in Euro je Kubikmeter ( $€ / \mathrm{m}^{3}$ ) Schmutzwasser (SW) wiedergegeben. Hierbei handelt es sich um grobe Richtwerte, die auf Basis von Kostenkurven und weiteren Erfahrungswerten zusammengestellt und mithilfe von Baupreisindizes auf das Jahr 2020 umgerechnet wurden. Die unteren Werte beziehen sich auf große Kläranlagen mit Ausbaugrößen von ca. 100.000 E , die oberen Werte stehen für kleinere Anlagen von ca. 10.000 E :', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
